type byAge []Person
func (s byAge) Len() int           { return len(s) }
func (s byAge) Less(i, j int) bool { return s[i].Age < s[j].Age }
func (s byAge) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

sort.Sort(byAge(people))   // servant = the algorithm in package sort;
// the serviced type supplies only the three primitives, no declaration needed
